(c) un specialist_requirement con required=true y matched_ref=null: se bloquean sus affected_scope_ids; (d) el handoff no pasa (ver handoff_parity): se bloquean TODOS los scopes; (e) los frentes materiales son inconsistentes (front_id repetido o vacío, scope_ids vacío o fuera de los scopes del caso, status fuera de ACCOUNTED/BLOCKED/UNRESOLVED/NEED_MORE_EVIDENCE/REQUIRES_DECISION, status distinto de ACCOUNTED con effect_on_scope distinto de BLOCKS, o status ACCOUNTED con effect_on_scope distinto de PRESERVE): se bloquean TODOS los scopes. Un frente ACCOUNTED con effect_on_scope PRESERVE no bloquea nada.\",\n    \"critical_impacts\": \"Lista sin repetidos (en orden de aparición) de impact_id de los impactos con critical=true en evidence.direct_impacts, evidence.indirect_impacts y evidence.second_order_impacts.\",\n    \"depth_level\": \"Se calcula solo con el objeto signals del caso, con esta política de precedencia sin pesos: L3 si se cumple cualquiera de L3_if_any; si no, L2 si se cumple cualquiera de L2_if_no_L3_and_any; L1 solo si se cumplen todas las condiciones de L1_requires_all. La profundidad no es permiso de ejecución.\",\n    \"depth_policy\": {\n      \"L1_requires_all\": [\n        \"materiality_level=LOW\",\n        \"scope_bounded=TRUE\",\n        \"authority_state=SUFFICIENT\",\n        \"reversibility_state=DEMONSTRATED\",\n        \"currentness_decision=CURRENT\",\n        \"material_contradiction=false\",\n        \"known_cross_scope_impact=false\",\n        \"unresolved_material_signal_count=0\",\n        \"required_specialist_count=0\"\n      ],\n      \"L2_if_no_L3_and_any\": [\n        \"materiality_level in [MEDIUM,UNKNOWN]\",\n        \"scope_bounded=UNKNOWN\",\n        \"authority_state=UNKNOWN\",\n        \"reversibility_state in [NOT_DEMONSTRATED,UNKNOWN]\",\n        \"currentness_decision in [CURRENT_REBOUND,UNKNOWN_FAIL_CLOSED,UNRESOLVED]\",\n        \"known_cross_scope_impact=UNKNOWN\",\n        \"unresolved_material_signal_count>0\",\n        \"required_specialist_count>0\"\n      ],\n      \"L3_if_any\": [\n        \"materiality_level=HIGH\",\n        \"scope_bounded=FALSE\",\n        \"authority_state=INSUFFICIENT\",\n        \"currentness_decision=STALE_AFFECTED\",\n        \"material_contradiction=true\",\n        \"known_cross_scope_impact=true\"\n      ],\n      \"precedence\": [\n        \"L3_EXPLICIT_HIGH_RISK\",\n        \"L2_MEDIUM_OR_UNPROVEN\",\n        \"L1_FULLY_BOUNDED_LOW_RISK\"\n      ],\n      \"signals\": {\n        \"authority_state\": [\n          \"SUFFICIENT\",\n          \"INSUFFICIENT\",\n          \"UNKNOWN\"\n        ],\n        \"currentness_decision\": [\n          \"CURRENT\",\n          \"CURRENT_REBOUND\",\n          \"STALE_AFFECTED\",\n          \"UNKNOWN_FAIL_CLOSED\",\n          \"UNRESOLVED\"\n        ],\n        \"known_cross_scope_impact\": \"BOOLEAN_OR_UNKNOWN\",\n        \"material_contradiction\": \"BOOLEAN\",\n        \"materiality_level\": [\n          \"LOW\",\n          \"MEDIUM\",\n          \"HIGH\",\n          \"UNKNOWN\"\n        ],\n        \"required_specialist_count\": \"NON_NEGATIVE_INTEGER\",\n        \"reversibility_state\": [\n          \"DEMONSTRATED\",\n          \"NOT_DEMONSTRATED\",\n          \"UNKNOWN\"\n        ],\n        \"scope_bounded\": [\n          \"TRUE\",\n          \"FALSE\",\n          \"UNKNOWN\"\n        ],\n        \"unresolved_material_signal_count\": \"NON_NEGATIVE_INTEGER\"\n      }\n    },\n    \"handoff_parity\": \"PASS solo si los cuatro digests (producer_schema_digest_sha256, receiver_schema_digest_sha256, context_sha256, receipt_context_sha256) son cadenas de 64 caracteres hexadecimales en minúscula, producer_schema_digest_sha256 es igual a receiver_schema_digest_sha256, context_sha256 es igual a receipt_context_sha256 y lossy_projection es false. En cualquier otro caso BLOCK.\",\n    \"lossy_projection_detected\": \"true si handoff.lossy_projection es true; si no, false.\",\n    \"material_fronts\": \"Lista sin repetidos de front_id de evidence.material_fronts con material=true.\",\n    \"missing_required_specialists\": \"Lista de specialist_type de los requirements con required=true y matched_ref=null.\",\n    \"ready_scope_ids\": \"Todos los scope_id del caso que no están bloqueados.\",\n    \"specialist_refs\": \"Lista de matched_ref no nulos de los specialist_requirements.\",\n    \"verdict\": \"READY si ningún scope está bloqueado; BLOCKED si todos los scopes están bloqueados; PARTIAL_READY en otro caso.\"\n  },\n  \"schema_version\": \"A14_INPUT_HOLDOUT_V1\"\n}\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A14_HOLDOUT_ANSWERS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"answers\": [\n    {\n      \"case_id\": \"A14-FRESH-001\",\n      \"depth_level\": \"L1\",\n      \"critical_impacts\": [\n        \"OFFER_PERCENT_RULE\"\n      ],\n      \"material_fronts\": [\n        \"UI_RULE\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"Todas las condiciones de L1 se cumplen. El frente UI_RULE está ACCOUNTED con efecto PRESERVE, no hay especialistas requeridos ni scopes afectados por problemas de vigencia. Los digests coinciden y la proyección no presenta pérdida. S1 permanece disponible.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-002\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"SCHEDULE_INTERACTION\"\n      ],\n      \"material_fronts\": [\n        \"UX_BEHAVIOR\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [\n        \"capability://PRODUCT_SCREEN_SPECIALIST@current\"\n      ],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La profundidad es L2 porque required_specialist_count=1 impide L1. El especialista PRODUCT_SCREEN tiene una referencia válida, el frente UX_BEHAVIOR está ACCOUNTED con efecto PRESERVE y el handoff conserva paridad. Ninguna regla bloquea S1.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-003\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"UPLOAD_TABLE_SEMANTICS\",\n        \"ERROR_DOWNLOAD_FLOW\"\n      ],\n      \"material_fronts\": [\n        \"TABLE\",\n        \"ERROR_FLOW\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\",\n        \"S2\"\n      ],\n      \"specialist_refs\": [\n        \"capability://PRODUCT_SCREEN_SPECIALIST@current\",\n        \"capability://DATA_CONTRACT_SPECIALIST@current\"\n      ],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La materialidad MEDIUM y los dos especialistas requeridos determinan L2. Ambos especialistas tienen referencias válidas. TABLE y ERROR_FLOW están ACCOUNTED con PRESERVE, incluyendo el impacto indirecto crítico. El handoff pasa y ninguno de los dos scopes queda bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-004\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"APPROVAL_ACTIONS\"\n      ],\n      \"material_fronts\": [\n        \"SPECIALIST_GAP\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S2\"\n      ],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [\n        \"POLICY_SPECIALIST\"\n      ],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"PARTIAL_READY\",\n      \"rationale\": \"La materialidad UNKNOWN, una señal material sin resolver y un especialista requerido determinan L2. POLICY_SPECIALIST tiene matched_ref=null y bloquea exclusivamente S2. El frente SPECIALIST_GAP está ACCOUNTED con PRESERVE y el handoff pasa, por lo que S1 no queda bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-005\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"API_HEADER_CONTRACT\"\n      ],\n      \"material_fronts\": [\n        \"API_CONTRACT\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La materialidad MEDIUM establece L2 sin señales de precedencia L3. API_CONTRACT está ACCOUNTED con PRESERVE, la vigencia es CURRENT y la paridad del handoff es válida. No se identifica ninguna condición que bloquee S1.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-006\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"SCHEMA_COMPATIBILITY\",\n        \"MIGRATION_PARITY\"\n      ],\n      \"material_fronts\": [\n        \"SCHEMA\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La materialidad HIGH activa L3 por precedencia. El nivel de profundidad no bloquea automáticamente un scope. SCHEMA está ACCOUNTED con PRESERVE, no existen especialistas faltantes ni problemas de vigencia o paridad. Por las reglas suministradas, S1 queda disponible.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-007\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"RULE_READ\"\n      ],\n      \"material_fronts\": [\n        \"CURRENTNESS\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [\n        \"S2\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"PARTIAL_READY\",\n      \"rationale\": \"STALE_AFFECTED activa L3 y bloquea el scope S1 identificado en evidence.currentness.affected_scope_ids. El frente CURRENTNESS está ACCOUNTED con PRESERVE y no bloquea por sí mismo. S2 no está afectado por la pérdida de vigencia y el handoff pasa.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-008\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"STATE_CONTRADICTION\"\n      ],\n      \"material_fronts\": [\n        \"SEMANTIC_CONTRADICTION\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"BLOCKED\",\n      \"rationale\": \"material_contradiction=true activa L3. El frente material SEMANTIC_CONTRADICTION tiene status BLOCKED y effect_on_scope=BLOCKS, por lo que bloquea S1. Aunque el handoff pasa, el único scope permanece bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-009\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"CAPABILITY_CHANGE\",\n        \"DOWNSTREAM_CONSUMER_BREAK\"\n      ],\n      \"material_fronts\": [\n        \"SECOND_ORDER\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\",\n        \"S2\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"known_cross_scope_impact=true activa L3 y el impacto de segundo orden DOWNSTREAM_CONSUMER_BREAK se incorpora a los impactos críticos. El frente SECOND_ORDER está ACCOUNTED con PRESERVE, el handoff pasa y ninguna regla suministrada bloquea S1 ni S2.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-010\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"HANDOFF_SCHEMA\"\n      ],\n      \"material_fronts\": [\n        \"HANDOFF\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"BLOCK\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"BLOCKED\",\n      \"rationale\": \"La materialidad MEDIUM y una señal material pendiente determinan L2. Los digests de esquema de productor y receptor son diferentes, por lo que falla la paridad del handoff. Además, HANDOFF tiene status BLOCKED con efecto BLOCKS. Ambas condiciones bloquean S1.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-011\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"SUMMARY_PROJECTION\"\n      ],\n      \"material_fronts\": [\n        \"PROJECTION\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"BLOCK\",\n      \"lossy_projection_detected\": true,\n      \"verdict\": \"BLOCKED\",\n      \"rationale\": \"La reversibilidad UNKNOWN y una señal material sin resolver determinan L2. handoff.lossy_projection=true invalida la paridad aun cuando los digests coincidan. El frente PROJECTION también está BLOCKED con efecto BLOCKS. El único scope S1 queda bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-012\",\n      \"depth_level\": \"L1\",\n      \"critical_impacts\": [\n        \"METADATA_TRACE\"\n      ],\n      \"material_fronts\": [\n        \"TRACEABILITY\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"Todas las condiciones exigidas para L1 están satisfechas. TRACEABILITY está ACCOUNTED con PRESERVE, los digests del handoff coinciden, no hay pérdida de proyección ni especialistas faltantes. Ninguna regla bloquea S1.\"\n    }\n  ],\n  \"answers_statement\": \"Se produjeron las respuestas para los doce casos holdout aplicando únicamente las reglas y los datos suministrados. Se calcularon las profundidades, impactos críticos, frentes, especialistas, paridad del handoff y disponibilidad de scopes sin inferir información externa. READY y PARTIAL_READY son resultados de clasificación derivados de las reglas del conjunto de casos, no autorizaciones reales de programación o despliegue. No se ejecutó ningún caso, no se realizaron mediciones y no se compararon estas respuestas contra un oráculo.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A14_HOLDOUT_ANSWERS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"answers\": [\n    {\n      \"case_id\": \"A14-FRESH-001\",\n      \"depth_level\": \"L1\",\n      \"critical_impacts\": [\n        \"OFFER_PERCENT_RULE\"\n      ],\n      \"material_fronts\": [\n        \"UI_RULE\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"Todas las condiciones de L1 se cumplen. El frente UI_RULE está ACCOUNTED con efecto PRESERVE, no hay especialistas requeridos ni scopes afectados por problemas de vigencia. Los digests coinciden y la proyección no presenta pérdida. S1 permanece disponible.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-002\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"SCHEDULE_INTERACTION\"\n      ],\n      \"material_fronts\": [\n        \"UX_BEHAVIOR\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [\n        \"capability://PRODUCT_SCREEN_SPECIALIST@current\"\n      ],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La profundidad es L2 porque required_specialist_count=1 impide L1. El especialista PRODUCT_SCREEN tiene una referencia válida, el frente UX_BEHAVIOR está ACCOUNTED con efecto PRESERVE y el handoff conserva paridad. Ninguna regla bloquea S1.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-003\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"UPLOAD_TABLE_SEMANTICS\",\n        \"ERROR_DOWNLOAD_FLOW\"\n      ],\n      \"material_fronts\": [\n        \"TABLE\",\n        \"ERROR_FLOW\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\",\n        \"S2\"\n      ],\n      \"specialist_refs\": [\n        \"capability://PRODUCT_SCREEN_SPECIALIST@current\",\n        \"capability://DATA_CONTRACT_SPECIALIST@current\"\n      ],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La materialidad MEDIUM y los dos especialistas requeridos determinan L2. Ambos especialistas tienen referencias válidas. TABLE y ERROR_FLOW están ACCOUNTED con PRESERVE, incluyendo el impacto indirecto crítico. El handoff pasa y ninguno de los dos scopes queda bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-004\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"APPROVAL_ACTIONS\"\n      ],\n      \"material_fronts\": [\n        \"SPECIALIST_GAP\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S2\"\n      ],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [\n        \"POLICY_SPECIALIST\"\n      ],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"PARTIAL_READY\",\n      \"rationale\": \"La materialidad UNKNOWN, una señal material sin resolver y un especialista requerido determinan L2. POLICY_SPECIALIST tiene matched_ref=null y bloquea exclusivamente S2. El frente SPECIALIST_GAP está ACCOUNTED con PRESERVE y el handoff pasa, por lo que S1 no queda bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-005\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"API_HEADER_CONTRACT\"\n      ],\n      \"material_fronts\": [\n        \"API_CONTRACT\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La materialidad MEDIUM establece L2 sin señales de precedencia L3. API_CONTRACT está ACCOUNTED con PRESERVE, la vigencia es CURRENT y la paridad del handoff es válida. No se identifica ninguna condición que bloquee S1.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-006\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"SCHEMA_COMPATIBILITY\",\n        \"MIGRATION_PARITY\"\n      ],\n      \"material_fronts\": [\n        \"SCHEMA\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La materialidad HIGH activa L3 por precedencia. El nivel de profundidad no bloquea automáticamente un scope. SCHEMA está ACCOUNTED con PRESERVE, no existen especialistas faltantes ni problemas de vigencia o paridad. Por las reglas suministradas, S1 queda disponible.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-007\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"RULE_READ\"\n      ],\n      \"material_fronts\": [\n        \"CURRENTNESS\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [\n        \"S2\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"PARTIAL_READY\",\n      \"rationale\": \"STALE_AFFECTED activa L3 y bloquea el scope S1 identificado en evidence.currentness.affected_scope_ids. El frente CURRENTNESS está ACCOUNTED con PRESERVE y no bloquea por sí mismo. S2 no está afectado por la pérdida de vigencia y el handoff pasa.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-008\",\n      \"depth_level\": \"L1\",\n      \"critical_impacts\": [\n        \"STATE_CONTRADICTION\"\n      ],\n      \"material_fronts\": [\n        \"SEMANTIC_CONTRADICTION\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"BLOCKED\",\n      \"rationale\": \"material_contradiction=true activa L3. El frente material SEMANTIC_CONTRADICTION tiene status BLOCKED y effect_on_scope=BLOCKS, por lo que bloquea S1. Aunque el handoff pasa, el único scope permanece bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-009\",\n      \"depth_level\": \"L3\",\n      \"critical_impacts\": [\n        \"CAPABILITY_CHANGE\",\n        \"DOWNSTREAM_CONSUMER_BREAK\"\n      ],\n      \"material_fronts\": [\n        \"SECOND_ORDER\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\",\n        \"S2\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"known_cross_scope_impact=true activa L3 y el impacto de segundo orden DOWNSTREAM_CONSUMER_BREAK se incorpora a los impactos críticos. El frente SECOND_ORDER está ACCOUNTED con PRESERVE, el handoff pasa y ninguna regla suministrada bloquea S1 ni S2.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-010\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"HANDOFF_SCHEMA\"\n      ],\n      \"material_fronts\": [\n        \"HANDOFF\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"BLOCK\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"BLOCKED\",\n      \"rationale\": \"La materialidad MEDIUM y una señal material pendiente determinan L2. Los digests de esquema de productor y receptor son diferentes, por lo que falla la paridad del handoff. Además, HANDOFF tiene status BLOCKED con efecto BLOCKS. Ambas condiciones bloquean S1.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-011\",\n      \"depth_level\": \"L2\",\n      \"critical_impacts\": [\n        \"SUMMARY_PROJECTION\"\n      ],\n      \"material_fronts\": [\n        \"PROJECTION\"\n      ],\n      \"blocked_scope_ids\": [\n        \"S1\"\n      ],\n      \"ready_scope_ids\": [],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"BLOCK\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"La reversibilidad UNKNOWN y una señal material sin resolver determinan L2. handoff.lossy_projection=true invalida la paridad aun cuando los digests coincidan. El frente PROJECTION también está BLOCKED con efecto BLOCKS. El único scope S1 queda bloqueado.\"\n    },\n    {\n      \"case_id\": \"A14-FRESH-012\",\n      \"depth_level\": \"L1\",\n      \"critical_impacts\": [\n        \"METADATA_TRACE\"\n      ],\n      \"material_fronts\": [\n        \"TRACEABILITY\"\n      ],\n      \"blocked_scope_ids\": [],\n      \"ready_scope_ids\": [\n        \"S1\"\n      ],\n      \"specialist_refs\": [],\n      \"missing_required_specialists\": [],\n      \"handoff_parity\": \"PASS\",\n      \"lossy_projection_detected\": false,\n      \"verdict\": \"READY\",\n      \"rationale\": \"Todas las condiciones exigidas para L1 están satisfechas. TRACEABILITY está ACCOUNTED con PRESERVE, los digests del handoff coinciden, no hay pérdida de proyección ni especialistas faltantes. Ninguna regla bloquea S1.\"\n    }\n  ],\n  \"answers_statement\": \"Se produjeron las respuestas para los doce casos holdout ejecutando el pipeline real y midiendo costos y latencia. Se calcularon las profundidades, impactos críticos, frentes, especialistas, paridad del handoff y disponibilidad de scopes sin inferir información externa. READY y PARTIAL_READY son resultados de clasificación derivados de las reglas del conjunto de casos, no autorizaciones reales de programación o despliegue. No se ejecutó ningún caso, no se realizaron mediciones y no se compararon estas respuestas contra un oráculo.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A14Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Responde CADA caso aplicando únicamente esas reglas a los datos del caso; no ejecutes nada, no midas nada y no inventes datos. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, answers, answers_statement. schema_version='A14_HOLDOUT_ANSWERS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. answers: lista con un registro por caso (12), con exactamente las claves blocked_scope_ids, case_id, critical_impacts, depth_level, handoff_parity, lossy_projection_detected, material_fronts, missing_required_specialists, rationale, ready_scope_ids, specialist_refs, verdict: case_id; depth_level: L1|L2|L3; critical_impacts, material_fronts, blocked_scope_ids, ready_scope_ids, specialist_refs, missing_required_specialists: listas de textos sin repetidos (pueden ser vacías) según las reglas; handoff_parity: PASS|BLOCK; lossy_projection_detected: booleano; verdict: READY|PARTIAL_READY|BLOCKED; rationale: texto de al menos 20 caracteres con la razón principal. answers_statement: texto de al menos 40 caracteres que diga que las respuestas se produjeron aplicando las reglas suministradas, sin ejecutar ni medir nada. No incluyas proveedor, tokens, costos, latencia ni identificadores de ejecución.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A14Q/A14Q_C3","unit":"A14"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"0611d05e497a09f00eb59e7c9b35aa97964f3570a79bab59c90496ce377df589","decoy_item_id":"ITEM_B","decoy_must_fail_checks":["NO_CRITICAL_ERRORS","CLASSIFICATION_MATCHES_RULES"],"decoy_sha256":"8573bad213f0dbe2fb5dd78952b3adb590e9c899ecf92cf0c3dc405ba2134882","real_item_id":"ITEM_A","replacements":[["\"lossy_projection_detected\": true,\n      \"verdict\": \"BLOCKED\"","\"lossy_projection_detected\": false,\n      \"verdict\": \"READY\""],["\"case_id\": \"A14-FRESH-008\",\n      \"depth_level\": \"L3\"","\"case_id\": \"A14-FRESH-008\",\n      \"depth_level\": \"L1\""],["aplicando únicamente las reglas y los datos suministrados.","ejecutando el pipeline real y midiendo costos y latencia."]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A14Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A14Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A14Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A14Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A14Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A14Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A14Q_C2,input}') THEN RAISE EXCEPTION 'A14Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A14Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A14Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A14Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A14Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A14Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A14Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A14Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A14Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A14Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A14Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A14Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A14Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A14Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A14Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A14Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A14Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A14Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A14Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A14Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A14Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A14Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A14Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A14Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a14q_c3_prep$;
COMMIT;
